/* Ardzy - languages: English (the app's own text), Greek, Russian.
   The page is written in English; this file translates every text it knows, also the parts the views make
   later (a MutationObserver): texts, tooltips (title) and placeholders. Code, terminals and drawings stay as
   they are. Blockly's own blocks come with Blockly's translations (vendor/blockly/el.js, ru.js); the Ardzy
   blocks are translated here (i18nBlocks). The language is chosen in App settings (the window reloads). */

const I18N_LANGS = { en: 'English', el: 'Ελληνικά', ru: 'Русский' };
const I18N_LANG = (() => {
  const h = (location.hash.match(/lang=(en|el|ru)/) || [])[1];          // a link can choose it: #lang=el
  try { if (h) localStorage.setItem('ardzy.lang', h); return h || localStorage.getItem('ardzy.lang') || 'en'; } catch (e) { return h || 'en'; }
})();

